// Generated by tools/build-godot-template.js. Edit export-templates/godot instead.
const godotTemplate = {
  "README.md": "# Dialogue Playground — Godot 4\n\nThe downloadable apple-quest demo: talk to Mira, close the conversation, touch\nthe red apple with green leaves, then return to Mira. Pickup removes the apple\nand sets numeric `hasApple = 1`; Mira's root conditions select the request at\n`hasApple = 0` and the thank-you at `hasApple = 1`. Returning before pickup still\nshows the request. Restart Play/Preview to reset. The pickup is enabled only\nwhen the source demo's `demoAppleQuest` flag is true.\n\nExtract this ZIP, import project.godot in Godot 4.5 or newer, and press F6\n(current scene) or F5 (project). No plugins, .NET, or external assets are required.\n\nMove the blue player with arrows or WASD and touch a colored NPC to talk.\nClick choices or use Tab and Enter. Escape closes dialogue and the variable\npanel. Move away and return to the NPC to restart the conversation.\n\nEvery character tree has its own NPC scene instance, even if names are identical.\nThe world grows vertically for larger casts, and the player's camera follows.\nEmpty trees show a message instead of failing. Newlines advance as dialogue pages;\nlong pages and lists of answers scroll in the dialogue panel.\n\nUse Test variables to change conditions. Numeric variables start at 0 and strings\nstart empty. All conditions on an edge must pass. Normal nodes select the first\navailable outgoing edge; Next is used only when there are no outgoing edges.\nFight nodes offer simulated win/loss choices, not a combat system.\n\nEdit scenes/main.tscn to reposition characters, scenes/player.tscn and\nscenes/npc.tscn to customize their shapes, and scenes/dialogue_ui.tscn for the UI.\nNPCs use Area2D.body_entered to detect the CharacterBody2D player. Movement pauses\nwhile a conversation or test panel is open. The areas are contact triggers;\nthey do not act as solid obstacles.\n\nDialogue is in dialogue.json. NPC character_index maps to its characters array.\nExport again after adding or removing characters. To integrate with your game,\nset DialogueUI.variables, replace the test panel with your own game state,\nand use dialogue_session.gd for traversal. The exporter preserves original\nnames and text in JSON rather than treating them as scene names or script code.\n",
  "scenes/dialogue_ui.tscn": "[gd_scene load_steps=2 format=3]\n\n[ext_resource type=\"Script\" path=\"res://scripts/dialogue_ui.gd\" id=\"1\"]\n\n[node name=\"DialogueUI\" type=\"CanvasLayer\"]\nscript = ExtResource(\"1\")\n\n[node name=\"HUD\" type=\"MarginContainer\" parent=\".\"]\nanchor_right = 1.0\noffset_left = 16.0\noffset_top = 16.0\noffset_right = -16.0\noffset_bottom = 76.0\n\n[node name=\"Row\" type=\"HBoxContainer\" parent=\"HUD\"]\nlayout_mode = 2\ntheme_override_constants/separation = 16\n\n[node name=\"Instructions\" type=\"Label\" parent=\"HUD/Row\"]\nlayout_mode = 2\nsize_flags_horizontal = 3\ntext = \"Move: arrows / WASD | Touch an NPC to talk\\nEnter / click: choose | Esc: close | Blue square = you\"\nautowrap_mode = 3\n\n[node name=\"Variables\" type=\"Button\" parent=\"HUD/Row\"]\nlayout_mode = 2\ntext = \"Test variables\"\n\n[node name=\"DialoguePanel\" type=\"PanelContainer\" parent=\".\"]\nvisible = false\nanchor_top = 1.0\nanchor_right = 1.0\nanchor_bottom = 1.0\noffset_left = 24.0\noffset_top = -320.0\noffset_right = -24.0\noffset_bottom = -24.0\ngrow_horizontal = 2\ngrow_vertical = 0\n\n[node name=\"Margin\" type=\"MarginContainer\" parent=\"DialoguePanel\"]\nlayout_mode = 2\ntheme_override_constants/margin_left = 20\ntheme_override_constants/margin_top = 16\ntheme_override_constants/margin_right = 20\ntheme_override_constants/margin_bottom = 16\n\n[node name=\"Scroll\" type=\"ScrollContainer\" parent=\"DialoguePanel/Margin\"]\nlayout_mode = 2\nhorizontal_scroll_mode = 0\n\n[node name=\"Content\" type=\"VBoxContainer\" parent=\"DialoguePanel/Margin/Scroll\"]\nlayout_mode = 2\nsize_flags_horizontal = 3\ntheme_override_constants/separation = 10\n\n[node name=\"Speaker\" type=\"Label\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\ntheme_override_colors/font_color = Color(0.6, 0.85, 1, 1)\ntheme_override_font_sizes/font_size = 24\nautowrap_mode = 3\n\n[node name=\"Line\" type=\"Label\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\nautowrap_mode = 3\n\n[node name=\"Choices\" type=\"VBoxContainer\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\ntheme_override_constants/separation = 8\n\n[node name=\"Hint\" type=\"Label\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\nautowrap_mode = 3\n\n[node name=\"Close\" type=\"Button\" parent=\"DialoguePanel/Margin/Scroll/Content\"]\nlayout_mode = 2\ntext = \"Close conversation (Esc)\"\n\n[node name=\"VariablePanel\" type=\"PanelContainer\" parent=\".\"]\nvisible = false\nanchor_left = 1.0\nanchor_right = 1.0\noffset_left = -460.0\noffset_top = 86.0\noffset_right = -24.0\noffset_bottom = 300.0\ngrow_horizontal = 0\n\n[node name=\"Margin\" type=\"MarginContainer\" parent=\"VariablePanel\"]\nlayout_mode = 2\ntheme_override_constants/margin_left = 16\ntheme_override_constants/margin_top = 16\ntheme_override_constants/margin_right = 16\ntheme_override_constants/margin_bottom = 16\n\n[node name=\"Scroll\" type=\"ScrollContainer\" parent=\"VariablePanel/Margin\"]\nlayout_mode = 2\nhorizontal_scroll_mode = 0\n\n[node name=\"Rows\" type=\"VBoxContainer\" parent=\"VariablePanel/Margin/Scroll\"]\nlayout_mode = 2\nsize_flags_horizontal = 3\ntheme_override_constants/separation = 8\n\n[node name=\"Explanation\" type=\"Label\" parent=\"VariablePanel/Margin/Scroll/Rows\"]\nlayout_mode = 2\ntext = \"Change variables to test conditional paths.\\nFights provide simulated win/loss choices.\"\nautowrap_mode = 3\n\n[node name=\"Close\" type=\"Button\" parent=\"VariablePanel/Margin/Scroll/Rows\"]\nlayout_mode = 2\ntext = \"Close test variables\"\n",
  "scenes/npc.tscn": "[gd_scene load_steps=3 format=3]\n\n[ext_resource type=\"Script\" path=\"res://scripts/npc.gd\" id=\"1\"]\n[sub_resource type=\"RectangleShape2D\" id=\"Shape\"]\nsize = Vector2(32, 32)\n\n[node name=\"NPC\" type=\"Area2D\"]\ncollision_layer = 0\ncollision_mask = 1\nscript = ExtResource(\"1\")\n\n[node name=\"Body\" type=\"Polygon2D\" parent=\".\"]\npolygon = PackedVector2Array(-16, -16, 16, -16, 16, 16, -16, 16)\n\n[node name=\"CollisionShape2D\" type=\"CollisionShape2D\" parent=\".\"]\nshape = SubResource(\"Shape\")\n\n[node name=\"NameLabel\" type=\"Label\" parent=\".\"]\noffset_left = -90.0\noffset_top = 24.0\noffset_right = 90.0\noffset_bottom = 86.0\nhorizontal_alignment = 1\nautowrap_mode = 3\n",
  "scenes/player.tscn": "[gd_scene load_steps=3 format=3]\n\n[ext_resource type=\"Script\" path=\"res://scripts/player.gd\" id=\"1\"]\n[sub_resource type=\"RectangleShape2D\" id=\"Shape\"]\nsize = Vector2(32, 32)\n\n[node name=\"Player\" type=\"CharacterBody2D\" groups=[\"player\"]]\ncollision_layer = 1\ncollision_mask = 2\nmotion_mode = 1\nscript = ExtResource(\"1\")\n\n[node name=\"Body\" type=\"Polygon2D\" parent=\".\"]\npolygon = PackedVector2Array(-16, -16, 16, -16, 16, 16, -16, 16)\ncolor = Color(0.35, 0.8, 1, 1)\n\n[node name=\"CollisionShape2D\" type=\"CollisionShape2D\" parent=\".\"]\nshape = SubResource(\"Shape\")\n\n[node name=\"NameLabel\" type=\"Label\" parent=\".\"]\noffset_left = -60.0\noffset_top = 22.0\noffset_right = 60.0\noffset_bottom = 50.0\ntext = \"YOU\"\nhorizontal_alignment = 1\n\n[node name=\"Camera2D\" type=\"Camera2D\" parent=\".\"]\nlimit_left = 0\nlimit_top = 0\nlimit_right = 960\nlimit_bottom = 640\n",
  "scripts/dialogue_session.gd": "extends RefCounted\n## Engine-independent traversal. Variables are shared with the playground.\n\nvar character: Dictionary\nvar variables: Dictionary\nvar nodes: Dictionary = {}\nvar current: Dictionary = {}\n\nfunc _init(data: Dictionary, game_variables: Dictionary) -> void:\n\tcharacter = data\n\tvariables = game_variables\n\tfor node in character.get(\"dialogueNodes\", []):\n\t\tnodes[str(int(node.dialogueID))] = node\n\nfunc go(id: Variant) -> Dictionary:\n\tcurrent = nodes.get(str(int(id)) if id != null else \"\", {})\n\treturn current\n\nfunc allows(line: Dictionary) -> bool:\n\tfor condition in line.get(\"transitionConditions\", []):\n\t\tvar actual: Variant = variables.get(condition.variableName)\n\t\tvar expected: Variant = condition.variableValue\n\t\t# JSON numbers are floats. Compare numbers numerically, strings as strings.\n\t\tvar same_type := (actual is float or actual is int) and (expected is float or expected is int)\n\t\tsame_type = same_type or (actual is String and expected is String)\n\t\tvar passes := false\n\t\tmatch condition.comparisonOperator:\n\t\t\t\"=\": passes = same_type and actual == expected\n\t\t\t\"!=\": passes = not same_type or actual != expected\n\t\t\t\"<\": passes = same_type and actual < expected\n\t\t\t\">\": passes = same_type and actual > expected\n\t\t\t\"<=\": passes = same_type and actual <= expected\n\t\t\t\">=\": passes = same_type and actual >= expected\n\t\tif not passes:\n\t\t\treturn false\n\treturn true\n\nfunc start() -> Dictionary:\n\tcurrent = {}\n\tfor line in character.get(\"outgoingLines\", []):\n\t\tif allows(line):\n\t\t\treturn go(line.toNode)\n\treturn current\n\nfunc can_advance(node: Dictionary) -> bool:\n\tvar lines: Array = node.get(\"outgoingLines\", [])\n\tif lines.is_empty():\n\t\treturn true\n\tfor line in lines:\n\t\tif allows(line):\n\t\t\treturn true\n\treturn false\n\nfunc advance(node: Dictionary) -> Dictionary:\n\tvar lines: Array = node.get(\"outgoingLines\", [])\n\tif lines.is_empty():\n\t\treturn go(node.get(\"nextNode\", -1))\n\tfor line in lines:\n\t\tif allows(line):\n\t\t\treturn go(line.toNode)\n\treturn current\n\nfunc options() -> Array:\n\tvar result: Array = []\n\tif current.is_empty():\n\t\treturn result\n\tvar lines: Array = current.get(\"outgoingLines\", [])\n\tmatch current.dialogueType:\n\t\t\"question\":\n\t\t\tfor line in lines:\n\t\t\t\tvar answer: Dictionary = nodes.get(str(int(line.toNode)), {})\n\t\t\t\tresult.append({\"text\": answer.get(\"dialogueText\", \"(Empty answer)\"),\n\t\t\t\t\t\"enabled\": allows(line) and can_advance(answer), \"node\": answer})\n\t\t\"fight\":\n\t\t\tfor index in range(lines.size()):\n\t\t\t\tvar label := \"Win the fight\" if index == 0 else \"Lose the fight\"\n\t\t\t\tif index > 1:\n\t\t\t\t\tlabel = \"Outcome %d\" % (index + 1)\n\t\t\t\tresult.append({\"text\": label, \"enabled\": allows(lines[index]), \"target\": lines[index].toNode})\n\t\t_:\n\t\t\tvar label := \"Continue\" if not lines.is_empty() or int(current.get(\"nextNode\", -1)) > 0 else \"Finish\"\n\t\t\tresult.append({\"text\": label, \"enabled\": can_advance(current), \"node\": current})\n\treturn result\n\nfunc choose(index: int) -> Dictionary:\n\tvar choices := options()\n\tif index < 0 or index >= choices.size() or not choices[index].enabled:\n\t\treturn current\n\tvar choice: Dictionary = choices[index]\n\tif choice.has(\"target\"):\n\t\treturn go(choice.target)\n\treturn advance(choice.node)\n",
  "scripts/dialogue_ui.gd": "extends CanvasLayer\n## Native Godot controls; no web view or external dependencies.\n\nsignal busy_changed(locked: bool)\nconst Session = preload(\"res://scripts/dialogue_session.gd\")\nvar characters: Array = []\nvar variables: Dictionary = {}\nvar session: RefCounted\nvar page: int = 0\n@onready var panel: PanelContainer = $DialoguePanel\n@onready var content: VBoxContainer = $DialoguePanel/Margin/Scroll/Content\n@onready var variable_panel: PanelContainer = $VariablePanel\n@onready var variable_rows: VBoxContainer = $VariablePanel/Margin/Scroll/Rows\n\nfunc _ready() -> void:\n\tcontent.get_node(\"Close\").pressed.connect(close_dialogue)\n\t$HUD/Row/Variables.pressed.connect(_toggle_variables)\n\tvariable_rows.get_node(\"Close\").pressed.connect(_toggle_variables)\n\nfunc configure(data: Array) -> void:\n\tcharacters = data\n\tfor character in characters:\n\t\tvar sources: Array = [character] + character.get(\"dialogueNodes\", [])\n\t\tfor source in sources:\n\t\t\tfor line in source.get(\"outgoingLines\", []):\n\t\t\t\tfor condition in line.get(\"transitionConditions\", []):\n\t\t\t\t\tif not variables.has(condition.variableName):\n\t\t\t\t\t\tvariables[condition.variableName] = 0.0 if condition.variableValue is float or condition.variableValue is int else \"\"\n\tfor key in variables:\n\t\tvar row := HBoxContainer.new()\n\t\trow.set_meta(\"variable_name\", key)\n\t\tvar label := Label.new()\n\t\tlabel.text = key\n\t\tlabel.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\t\trow.add_child(label)\n\t\tif variables[key] is float or variables[key] is int:\n\t\t\tvar input := SpinBox.new()\n\t\t\tinput.allow_greater = true\n\t\t\tinput.allow_lesser = true\n\t\t\tinput.step = 0.01\n\t\t\tinput.custom_minimum_size.x = 150\n\t\t\tinput.value_changed.connect(func(value: float): _set_variable(key, value))\n\t\t\trow.add_child(input)\n\t\telse:\n\t\t\tvar input := LineEdit.new()\n\t\t\tinput.custom_minimum_size.x = 150\n\t\t\tinput.text_changed.connect(func(value: String): _set_variable(key, value))\n\t\t\trow.add_child(input)\n\t\tvariable_rows.add_child(row)\n\nfunc _set_variable(key: String, value: Variant) -> void:\n\tvariables[key] = value\n\tif session != null:\n\t\t_render(false)\n\nfunc set_game_variable(key: String, value: Variant) -> void:\n\t_set_variable(key, value)\n\tfor row in variable_rows.get_children():\n\t\tif row.get_meta(\"variable_name\", \"\") == key:\n\t\t\tvar input = row.get_child(1)\n\t\t\tif input is SpinBox:\n\t\t\t\tinput.set_value_no_signal(float(value))\n\t\t\telif input is LineEdit:\n\t\t\t\tinput.text = str(value)\n\nfunc is_busy() -> bool:\n\treturn panel.visible or variable_panel.visible\n\nfunc _toggle_variables() -> void:\n\tvariable_panel.visible = not variable_panel.visible\n\tbusy_changed.emit(is_busy())\n\nfunc open_character(index: int) -> void:\n\tif is_busy() or index < 0 or index >= characters.size():\n\t\treturn\n\tsession = Session.new(characters[index], variables)\n\tsession.start()\n\tpage = 0\n\tpanel.show()\n\tbusy_changed.emit(true)\n\t_render()\n\nfunc close_dialogue() -> void:\n\tpanel.hide()\n\tsession = null\n\tbusy_changed.emit(is_busy())\n\nfunc _input(event: InputEvent) -> void:\n\tif event.is_action_pressed(\"ui_cancel\") and is_busy():\n\t\tvariable_panel.hide()\n\t\tclose_dialogue()\n\t\tget_viewport().set_input_as_handled()\n\nfunc _render(focus_choice: bool = true) -> void:\n\tif session == null:\n\t\treturn\n\tcontent.get_node(\"Speaker\").text = str(session.character.get(\"characterName\", \"Unnamed character\"))\n\tvar choices: VBoxContainer = content.get_node(\"Choices\")\n\tfor child in choices.get_children():\n\t\tchoices.remove_child(child)\n\t\tchild.queue_free()\n\tcontent.get_node(\"Hint\").text = \"\"\n\tif session.current.is_empty():\n\t\tcontent.get_node(\"Line\").text = \"No available starting dialogue. Check the root connection or test variables.\"\n\t\t_add_button(\"Try again\", func(): session.start(); page = 0; _render())\n\telse:\n\t\tvar pages := str(session.current.get(\"dialogueText\", \"\")).replace(\"\\r\\n\", \"\\n\").split(\"\\n\")\n\t\tcontent.get_node(\"Line\").text = pages[page]\n\t\tif page < pages.size() - 1:\n\t\t\t_add_button(\"Continue\", func(): page += 1; _render())\n\t\telse:\n\t\t\tvar options: Array = session.options()\n\t\t\tfor index in range(options.size()):\n\t\t\t\tvar option: Dictionary = options[index]\n\t\t\t\t_add_button(str(option.text), _choose.bind(index), option.enabled)\n\t\t\t\tif not option.enabled:\n\t\t\t\t\tcontent.get_node(\"Hint\").text = \"Some paths are locked. Use Test variables to try them.\"\n\t$DialoguePanel/Margin/Scroll.scroll_vertical = 0\n\tif focus_choice:\n\t\tfor child in choices.get_children():\n\t\t\tif not child.disabled:\n\t\t\t\tchild.grab_focus()\n\t\t\t\tbreak\n\nfunc _add_button(text: String, action: Callable, enabled: bool = true) -> void:\n\tvar button := Button.new()\n\tbutton.text = text\n\tbutton.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART\n\tbutton.custom_minimum_size.y = 40\n\tbutton.disabled = not enabled\n\tbutton.pressed.connect(action)\n\tcontent.get_node(\"Choices\").add_child(button)\n\nfunc _choose(index: int) -> void:\n\tsession.choose(index)\n\tpage = 0\n\tif session.current.is_empty():\n\t\tclose_dialogue()\n\telse:\n\t\t_render()\n\nfunc show_error(message: String) -> void:\n\tpanel.show()\n\tcontent.get_node(\"Speaker\").text = \"Dialogue error\"\n\tcontent.get_node(\"Line\").text = message\n",
  "scripts/main.gd": "extends Node2D\n\nvar apple: Area2D\n\nfunc _ready() -> void:\n\tvar text := FileAccess.get_file_as_string(\"res://dialogue.json\")\n\tvar data: Variant = JSON.parse_string(text)\n\tif not data is Dictionary or not data.get(\"characters\") is Array:\n\t\t$DialogueUI.show_error(\"Could not load dialogue.json. Check its JSON syntax.\")\n\t\t$Player.movement_locked = true\n\t\treturn\n\t$DialogueUI.configure(data.characters)\n\t$DialogueUI.busy_changed.connect(_on_busy_changed)\n\tfor npc in $NPCs.get_children():\n\t\tif npc.character_index >= data.characters.size():\n\t\t\tcontinue\n\t\tnpc.set_character_name(str(data.characters[npc.character_index].get(\"characterName\", \"Unnamed character\")))\n\t\tnpc.talk_requested.connect($DialogueUI.open_character)\n\t$Player/Camera2D.limit_bottom = int($Player.world_size.y)\n\tif data.get(\"demoAppleQuest\", false):\n\t\tapple = Area2D.new()\n\t\tapple.name = \"Apple\"\n\t\tapple.position = Vector2(580, 180)\n\t\tapple.collision_layer = 0\n\t\tapple.collision_mask = 1\n\t\tvar sprite := Sprite2D.new()\n\t\tsprite.texture = load(\"res://art/apple.png\")\n\t\tapple.add_child(sprite)\n\t\tvar collision := CollisionShape2D.new()\n\t\tvar shape := RectangleShape2D.new()\n\t\tshape.size = Vector2(28, 28)\n\t\tcollision.shape = shape\n\t\tapple.add_child(collision)\n\t\tapple.body_entered.connect(_pick_up_apple)\n\t\tadd_child(apple)\n\t\t$DialogueUI/HUD/Row/Instructions.text += \"\\nApple: not collected. Talk to Mira.\"\n\nfunc _pick_up_apple(body: Node2D) -> void:\n\tif body != $Player or not is_instance_valid(apple) or $DialogueUI.is_busy():\n\t\treturn\n\t$DialogueUI.set_game_variable(\"hasApple\", 1.0)\n\tapple.queue_free()\n\tapple = null\n\t$DialogueUI/HUD/Row/Instructions.text = \"Move: arrows / WASD. Apple collected! Return to Mira.\"\n\nfunc _on_busy_changed(locked: bool) -> void:\n\t$Player.movement_locked = locked\n",
  "scripts/npc.gd": "extends Area2D\n\nsignal talk_requested(character_index: int)\n@export var character_index: int = 0\n@export var tint := Color(\"b68af7\")\n\nfunc _ready() -> void:\n\t$Body.color = tint\n\tbody_entered.connect(_on_body_entered)\n\nfunc _on_body_entered(body: Node2D) -> void:\n\tif body.is_in_group(\"player\"):\n\t\ttalk_requested.emit(character_index)\n\nfunc set_character_name(value: String) -> void:\n\t$NameLabel.text = value\n",
  "scripts/player.gd": "extends CharacterBody2D\n\n@export var speed: float = 220.0\n@export var world_size := Vector2(960, 640)\nvar movement_locked: bool = false\n\nfunc _physics_process(_delta: float) -> void:\n\tif movement_locked:\n\t\tvelocity = Vector2.ZERO\n\t\treturn\n\tvelocity = Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\") * speed\n\tmove_and_slide()\n\tposition = position.clamp(Vector2(20, 100), world_size - Vector2(20, 20))\n"
};
if (typeof module !== "undefined") module.exports = godotTemplate;
